def parse_nested_parens(paren_string: str) -> List[int]:
    result = []
    max_depth = 0
    current_depth = 0

    for char in paren_string.split():
        for depth in char:
            if depth == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif depth == ')':
                current_depth -= 1

        result.append(max_depth)
        max_depth = 0
        current_depth = 0

    return result
